def num_comm_div(a, b):
    divisors_a = []
    divisors_b = []

    for i in range(1, a + 1):
        if a % i == 0:
            divisors_a.append(i)

    for i in range(1, b + 1):
        if b % i == 0:
            divisors_b.append(i)

